def _transcript_models(path: Path) -> list:
    """Sorted distinct models served on assistant turns of a transcript JSONL.

    Reads ONLY `message.model` on records whose `type` is `assistant` -- not
    every `"model"` substring in the file, which is what over-counted an
    attachment record's `claude-opus-5-5[1m]` alongside the real assistant
    turns in batch 20's own transcript. One trailing bracketed suffix
    (a context-window annotation, not a different model) is stripped from
    each result before it is deduplicated.
    """
    models = set()
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            if rec.get("type") != "assistant":
                continue
            msg = rec.get("message")
            if not isinstance(msg, dict):
                continue
            model = msg.get("model")
            if model:
                models.add(_MODEL_SUFFIX_RE.sub("", model))
    return sorted(models)


def _last_assistant_text(path: Path) -> str:
    """The text of the reviewer's final report in a transcript JSONL.

    THE LAST PLAIN TEXT BLOCK IS THE WRONG THING TO READ. In this harness a subagent's
    final report is delivered through a `SubagentHandback` TOOL CALL, not as trailing
    assistant prose -- a real reviewer transcript inspected during this feature's own
    adversarial review carried its whole findings report inside a `SubagentHandback`
    tool_use's `input.message`, followed by a separate, shorter plain-text turn
    ("I've sent the full adversarial pass ... back to the orchestrating session") that a
    last-text-block reader would return instead. The LAST `SubagentHandback` call in the
    transcript is preferred; only if none exists does this fall back to the last plain
    text block, for a reviewer run without that tool.
    """
    last_text, last_handback = "", None
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            if rec.get("type") != "assistant":
                continue
            msg = rec.get("message")
            if not isinstance(msg, dict):
                continue
            content = msg.get("content")
            if isinstance(content, str):
                last_text = content
            elif isinstance(content, list):
                texts = [b.get("text", "") for b in content
                         if isinstance(b, dict) and b.get("type") == "text"]
                if texts:
                    last_text = "\n".join(texts)
                for b in content:
                    if (isinstance(b, dict) and b.get("type") == "tool_use"
                            and b.get("name") in _HANDBACK_TOOL_NAMES):
                        inp = b.get("input") or {}
                        parts = [v for v in inp.values() if isinstance(v, str)]
                        if parts:
                            last_handback = "\n".join(parts)
    return last_handback if last_handback is not None else last_text


